// Content with portions generated by generative AI platform
package org.eclipse.kura.web;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Collections;
import org.eclipse.kura.web.server.GwtPasswordAuthenticationServiceImpl;
import org.eclipse.kura.web.session.Attributes;
import org.eclipse.kura.web.shared.GwtKuraException;
import org.eclipse.kura.web.shared.model.GwtPasswordAuthenticationResult;
import org.junit.Test;

/**
 * Feature: the password authentication service allocates a session only after the submitted credentials have been
 * successfully validated.
 */
public class PasswordAuthenticationSessionCreationTest extends WebConsoleSessionTestBase {

    private static final String PASSWORD_AUTH_PATH = "/admin/login/password";
    private static final String REDIRECT_PATH = "/admin/console";

    private TestablePasswordAuthenticationService service;
    private GwtPasswordAuthenticationResult result;
    private Exception error;

    @Test
    public void sessionIsCreatedAndAuthenticatedWithValidCredentials() throws Exception {
        givenConsole();
        givenPasswordAuthenticationService();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenAuthenticatingWith(VALID_USERNAME, VALID_PASSWORD);

        thenAuthenticationSucceeds();
        thenAuthenticatedSessionIsCreatedFor(VALID_USERNAME);
    }

    @Test
    public void noSessionIsCreatedWithWrongPassword() throws Exception {
        givenConsole();
        givenPasswordAuthenticationService();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenAuthenticatingWith(VALID_USERNAME, "wrong-password");

        thenAuthenticationFails();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedWithUnknownUser() throws Exception {
        givenConsole();
        givenPasswordAuthenticationService();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenAuthenticatingWith("unknown", VALID_PASSWORD);

        thenAuthenticationFails();
        thenNoSessionIsCreated();
    }

    @Test
    public void noSessionIsCreatedWhenPasswordAuthenticationIsDisabled() throws Exception {
        givenConsoleWithPasswordAuthenticationDisabled();
        givenPasswordAuthenticationService();
        givenRequestTo(PASSWORD_AUTH_PATH);

        whenAuthenticatingWith(VALID_USERNAME, VALID_PASSWORD);

        thenAuthenticationFails();
        thenNoSessionIsCreated();
    }

    private void givenConsoleWithPasswordAuthenticationDisabled() throws ReflectiveOperationException {
        givenConsoleWithOptions(Collections.singletonMap("auth.methodPassword", false));
    }

    private void givenPasswordAuthenticationService() {
        this.service = new TestablePasswordAuthenticationService(this.console.getUserManager());
    }

    private void whenAuthenticatingWith(final String username, final String password) {
        this.service.setThreadLocalRequest(this.request);

        try {
            this.result = this.service.authenticate(username, password);
        } catch (final Exception e) {
            this.error = e;
        }
    }

    private void thenAuthenticationSucceeds() {
        if (this.error != null) {
            throw new AssertionError("authentication should have succeeded", this.error);
        }
        assertNotNull(this.result);
        assertFalse(this.result.isPasswordUpdateRequired());
        assertEquals(REDIRECT_PATH, this.result.redirectPath());
    }

    private void thenAuthenticationFails() {
        if (this.error == null) {
            fail("authentication should have failed");
        }
        assertTrue(this.error instanceof GwtKuraException);
    }

    private void thenAuthenticatedSessionIsCreatedFor(final String username) {
        assertEquals("exactly one session should have been allocated", 1, this.sessionCreationCount);
        assertTrue("the session should still be valid", this.sessionValid);
        assertTrue("the session id should have been renewed", this.sessionIdChanged);
        assertEquals(username, this.sessionAttributes.get(Attributes.AUTORIZED_USER.getValue()));
        assertNotNull(this.sessionAttributes.get(Attributes.LAST_ACTIVITY.getValue()));
        assertNotNull(this.sessionAttributes.get(Attributes.AUDIT_CONTEXT.getValue()));
    }

    private void thenNoSessionIsCreated() {
        assertFalse("no session should have been allocated", isSessionAllocated());
    }

    private static final class TestablePasswordAuthenticationService extends GwtPasswordAuthenticationServiceImpl {

        private static final long serialVersionUID = 1L;

        TestablePasswordAuthenticationService(final UserManager userManager) {
            super(userManager, REDIRECT_PATH);
        }

        void setThreadLocalRequest(final jakarta.servlet.http.HttpServletRequest request) {
            this.perThreadRequest = new ThreadLocal<>();
            this.perThreadRequest.set(request);
        }
    }
}
